for d in "960 540" "390 844" "320 480" "320 568" "600 800" "700 500"; do echo "=== ui-game $d ==="; bun .beegame/delivery/check-content.mjs --layout-draft .beegame/tmp/ui-game.json $d --game-view game-view --camera .beegame/tmp/camera-draft.json 2>&1 | python3 -c "
import json,sys
try:
  r=json.load(sys.stdin)
  print('valid:',r.get('valid'))
  if r.get('issues'): print('issues:',r['issues'][:5])
  nodes=r.get('nodes') or r.get('layout',{}).get('nodes')
  # print brief rects
  def walk(ns,ind=0):
    for n in ns:
      print(' '*ind, n.get('id'), n.get('rect') or n.get('bounds'), 'outsideV' , n.get('outsideViewport'), 'outsideP', n.get('outsideParent'), 'outsideC', n.get('outsideContentArea'))
      if n.get('children'): walk(n['children'],ind+2)
  if nodes: walk(nodes)
  else: print(json.dumps(r)[:600])
except Exception as e:
  print('parse fail',e); 
"

